end

function Plugins.LoadAllPlugins()
    local paths = {}
    string.gsub(package.path, '[^;]+', function(w)
        table.insert(paths, w)
    end)
    local pluginPath = FileUtil:getMapPath() .. "/lua/plugins/"
    table.insert(paths, #paths - 1, pluginPath .. "?.lua")
    pluginPath = FileUtil:getScriptPath() .. "/lua/plugins/"
    table.insert(paths, #paths - 1, pluginPath .. "?.lua")
    pluginPath = FileUtil:getRootPath() .. "Media/Scripts/Engine/lua/plugins/"
    table.insert(paths, #paths - 1, pluginPath .. "?.lua")
    package.path = table.concat(paths, ";")
    local plugins = Global.setting.plugins or {}
    addEnginePlugin(plugins, "data_report")
    addEnginePlugin(plugins, "new_vip")
    for _, plugin in pairs(plugins) do
        Plugins.LoadPlugin(plugin)
    end
end

