function Plugins.LoadPlugin(plugin)
    if Plugins.IsLoaded(plugin) then
        return
    end
    local from = "map   "
    LogUtil.logInfo("[Plugins.LoadPlugin][      ][OnStart]", "plugin=" .. plugin)
    local pluginPath = FileUtil:getMapPath() .. "/lua/plugins/" .. plugin .. "/"
    local file = io.open(pluginPath .. plugin .. ".lua")
    if not file then
        from = "game  "
        pluginPath = FileUtil:getScriptPath() .. "/lua/plugins/" .. plugin .. "/"
        file = io.open(pluginPath .. plugin .. ".lua")
        if not file then
            if Platform.isLinux() then
                LogUtil.logWarning("[Plugins.LoadPlugin][game  ][Failed ]", pluginPath .. plugin .. ".lua" .. " is not exist!")
                return
            end
            from = "engine"
            pluginPath = FileUtil:getRootPath() .. "Media/Scripts/Engine/lua/plugins/" .. plugin .. "/"
            file = io.open(pluginPath .. plugin .. ".lua")
            if not file then
                LogUtil.logWarning("[Plugins.LoadPlugin][engine][Failed ]", pluginPath .. plugin .. ".lua" .. " is not exist!")
                return
            end
        end
    end
    file:close()
    if isClient then
        local paths = {}
        string.gsub(package.path, '[^;]+', function(w)
