    if type(func) == "function" then
        PluginFuncs[plugin] = func
        table.insert(PluginFuncArray, func)
    end
    PluginLoader[plugin] = true
    LogUtil.logInfo("[Plugins.LoadPlugin][".. from .."][Success]", "plugin=" .. plugin)
end

